\subsection{Nice Witness Structure, Nice Subinstances, and Statements of Main Theorems}
Let $G'$ be a graph, let $m>0$ be an integer with $|E(G')|\leq m$, and let $\cset'$ be a collection of disjoint clusters of $G'$. A \emph{nice witness structure} for $G'$ with respect to $\cset'$ consists of the following three main ingredients: 

\begin{enumerate}
	\item The first ingredient is a sequence $\tilde \sset=\set{\tilde S_1,\ldots,\tilde S_r}$ of disjoint vertex-induced subgraphs of $G'$, such that $\bigcup_{i=1}^rV(\tilde S_i)=V(G')$, and, for all $1\leq i\le r$, a cluster $\tilde S'_i\subseteq \tilde S_i$ that has the $\alpha^*=\Omega(1/\log^{12}m)$-bandwidth property in $G'$. We require that, for all $1\leq i\leq r$, there is at most one cluster $C \in\cset'$ with $C\subseteq \tilde S'_i$. Moreover, if such cluster $C$ exists then $E(\tilde S_i)\subseteq E(C)\cup E(G'_{|\cset'})$ must hold, and otherwise $E(\tilde S_i)\subseteq E(G'_{|\cset'})$. We also require that for each cluster $C\in \cset'$, there is an index $1\leq i\leq r$, such that $C\subseteq \tilde S_i'$. We refer to the sequence $\tilde \sset=\set{\tilde S_1,\ldots,\tilde S_r}$ as \emph{the backbone} of the nice witness structure, and to the clusters in $\tilde \sset'= \set{\tilde S'_1,\ldots,\tilde S'_r}$  as its \emph{verterbrae}. 

	\item The second ingredient is a partition of the edges of $E(G')$ into two disjoint subsets, $\tilde E'$ and $\tilde E''$. Set $\tilde E'$ contains all edges of $\bigcup_{i=1}^rE(\tilde S_i')$, and, additionally, for all $1\leq i<r$, it contains every edge $e=(u,v)$ with $u\in \tilde S_i'$, $v\in \tilde S_{i+1}'$. 
	Set $\tilde E''$ contains all remaining edges of $E(G')$.
	Additionally, we let $\hat E\subseteq \tilde E''$ be the set of all edges $(u,v)\in \tilde E''$, where $u$ and $v$ lie in different clusters of $\set{\tilde S_1,\ldots,\tilde S_r}$.

	\item The third ingerdient is a set $\hat \pset=\set{P(e)\mid e\in \hat E}$ of paths, that cause congestion at most $O(\log^{18} m)$ in $G'$ that we call \emph{nice guiding paths}. For each edge $e=(v,u)\in \hat E$, if we assume that $v\in \tilde S_i$, $u\in \tilde S_j$, and $i<j$, then path $P(e)$ connects vertex $v$ to vertex $u$, does not contain the edge $e$, and consists of three subpaths $P^1(e)$, $P^2(e)$ and $P^3(e)$, that have the following properties:

	\begin{itemize}
		\item There is an index $i'\leq i$, such that path $P^1(e)$ originates at vertex $v$ and terminates at some vertex $v'\in \tilde S'_{i'}$. Path $P^1(e)$ must be simple, and no vertex of $P^1(e)\setminus\set{v'}$ may lie in $\bigcup_{z=1}^rV(\tilde S_z')$.  Moreover, if we denote the sequence of vertices on path $P^1(e)$ by $v=v_0,v_1,\ldots,v_q=v'$, and, for all $0\leq z\leq q$, we assume that $v_z\in \tilde S_{i_z}$, then $i=i_0\geq i_1\geq\cdots\geq i_q=i'$.

		\item Similarly, there is an index $j'\geq j$, such that path $P^3(e)$ originates at vertex $u$ and terminates at some vertex $u'\in \tilde S'_{j'}$. Path $P^3(e)$ must be simple, and no vertex of $P^3(e)\setminus\set{u'}$ may lie in $\bigcup_{z=1}^rV(\tilde S_z')$.  Moreover, if we denote the sequence of vertices on path $P^3(e)$ by $u=u_0,u_1,\ldots,u_{q'}=u'$, and, for all $0\leq z'\leq q'$, we assume that $u_{z'}\in \tilde S_{j_{z'}}$, then $j=j_0\leq j_1\leq\cdots\leq j_{q'}=j'$.

		\item Lastly, path $P^2(e)$ connects $v'$ to $u'$. It may only use edges of $\tilde E'$, and it can be partitioned into disjoint subpaths $Q_{i'}(e),Q_{i'+1}(e),\ldots,Q_{j'}(e)$, where for all $i'\leq x\leq j'$, $Q_x(e)\subseteq \tilde S'_x$, and $\bigcup_{i'\leq x\leq j'}V(Q_x(e))=V(P^2(e))$.
	\end{itemize}
\end{enumerate}

For convenience, we will denote the set
$\tilde \sset'=\set{\tilde S'_1,\ldots, \tilde S'_r}$ of the vertebrae of the nice witness structure by $\sset=\set{S_1,\ldots,S_r}$.

\subsection{Disengagement of Nice Instances -- Proof of \Cref{thm: advanced disengagement - disengage nice instances}}
\label{subsec: disengagement with bad chain}

Throughout, we will use a parameter $\hat \eta=2^{O((\log m)^{3/4}\log\log m)}$.

\subsubsection{Step 1. Constructing the Paths of $\pset^{\out}$}

Throughout, we denote $V'=\bigcup_{S\in \sset}V(S)$ and $V''=V(G)\setminus V'$. 
Consider an edge $e=(u,v)\in \hat E$, and assume that $u\in S_i,v\in S_j$, and $i<j$. For convenience, we will call $u$ the \emph{left endpoint of edge $e$}, and $v$ the \emph{right endpoint of edge $e$}. 
We also define two sets of indices associated with edge $e$. The first set of indices is $\spann(e)=\set{i,i+1,\ldots,j-1}$. 
