\begin{definition}
	Let $R$ be a (directed) path in graph $G$ that contains at least one edge, let $(v_1,\ldots,v_z)$ be the sequence of vertices appearing on $R$, and, for all $1\leq a\leq z$, assume that $v_a\in \tilde S_{i_a}$. We say that $R$ is a \emph{left-monotone path} if:

	\begin{itemize} 
		\item $v_z\in V'$;
		\item for $1<a<z$, $v_a\in V''$; and 
		\item $i_1\geq i_2\geq\cdots\geq i_z$. 
		\end{itemize}
	Similarly, we say that $R$ is a \emph{right-monotone path}, if:

		\begin{itemize} 
		\item $v_z\in V'$;
		\item for $1<a<z$, $v_a\in V''$; and 
		\item $i_1\leq i_2\leq \cdots\leq i_z$. 
	\end{itemize}
\end{definition}

\begin{claim}\label{claim: computing out-paths}
	There is an efficient algorithm to compute two sets $\pset^{\out,\lef}=\set{P^{\out,\lef}(e)\mid e\in \hat E}$ and $\pset^{\out,\rig}=\set{P^{\out,\rig}(e)\mid e\in \hat E}$ of simple paths in graph $G$, each of which causes congestion at most  $\eta$, such that the paths in set $\pset^{\out,\lef}$ are non-transversal with respect to $\Sigma$, and so are the paths in set $\pset^{\out,\rig}$. Additionally, for every edge $e\in \hat E$, path $P^{\out,\lef}(e)$ has $e$ as its first edge, and it is left-monotone, while path $P^{\out,\rig}(e)$  has $e$ as its first edge, and is right-monotone. Moreover, for every vertex $v\in V'$, exactly $n_1(v)$ paths of $\pset^{\out,\lef}$ terminate at $v$, and exactly $n_3(v)$ paths of  $\pset^{\out,\rig}$ terminate at $v$.
\end{claim}

Consider now some edge $e=(u,v)\in \hat E$, and assume that $u\in \tilde S_i$, $v\in \tilde S_j$, and $i<j$ holds. Consider the paths $P^{\out,\lef}(e),P^{\out,\rig}(e)$. Assume that the last vertex on path $P^{\out,\lef}$ is $u'$, and the last vertex on path $P^{\out,\rig}$ is $v'$.  We let $P^{\out}(e)$ be the path obtained by concatenating path $P^{\out,\lef}(e)$ with the reversed path $P^{\out,\rig}(e)$, after deleting the extra copy of edge $e$...
Assume that $u'\in V(S_{i''})$ and $v'\in V(S_{j''})$. We define another set of indices associated with edge $e$: $\spann''(e)=\set{i'',i''+1,\ldots,j''-1}$. Notice that $\spann(e)\subseteq \spann''(e)$ must hold by the definition of left-monotone and right-monotone paths. Lastly, we set $\pset^{\out}=\set{P^{\out}(e)\mid e\in \hat E}$.

\subsubsection{Step 2: Constructing the Paths of $\pset^{\inn}$ and the Auxiliary Cycles}  

Consider again an edge $e\in \hat E$, and assume that $\spann''(e)=\set{i'',i''+1,\ldots,j''-1}$...
